- Python 3.11, standard library only.
- Keep functions small and name them after what they check or do.
- Every change comes with tests.
- `vendor/` is read-only; report problems with `ask_owner`.
```

`validators.py`:

```
"""Validators over depot run outputs. Each ``VN`` subclasses ``Check`` from ``checks_base``.

Callers use ``VN().run(items)``. ``check`` returns ``(passed, measured)``. When a validator
measures nothing, ``measured`` is an empty container, so ``Check.run`` reports
``failed: nothing measured``.
"""
from __future__ import annotations

from typing import Any, Iterable

from checks_base import Check, is_empty


def _is_int(x: Any) -> bool:
    """True for int values, excluding bool (a bool is not an integer cents amount)."""
    return isinstance(x, int) and not isinstance(x, bool)


class V1(Check):
    """Every report row's value matches units x cost."""

    name = "V1 rows: value_cents == units * unit_cost"

    def check(self, items: Iterable[dict]) -> tuple[bool, Any]:
        checked: list[tuple[str, str]] = []
        bad: list[tuple[str, str]] = []
        for row in items:
            sku = row["sku"]
            wh = row["wh"]
            ok = (
                isinstance(sku, str)
                and isinstance(wh, str)
                and _is_int(row["units"])
                and _is_int(row["value_cents"])
                and _is_int(row["unit_cost"])
                and row["value_cents"] == row["units"] * row["unit_cost"]
            )
            checked.append((sku, wh))
            if not ok:
                bad.append((sku, wh))
        return (not bad, {"checked": checked, "mismatched": bad})


class V2(Check):
    """All notification types in the spec were seen across a set of runs.

    ``EXPECTED`` is taken from the spec's event notifications (OVERDRAWN, REORDER, EXPIRY,
    AUDIT_MISMATCH, SUPPLIER_SUSPENDED). Errors are not notifications and are not included.
    """

    name = "V2 runs: every spec notification type seen"

    EXPECTED = frozenset(
        {"AUDIT_MISMATCH", "REORDER", "EXPIRY", "SUPPLIER_SUSPENDED", "OVERDRAWN"}
    )

    def __init__(self, expected: Iterable[str] | None = None) -> None:
        self.expected = frozenset(expected) if expected is not None else self.EXPECTED

    def check(self, items: Iterable[list]) -> tuple[bool, Any]:
        seen: set[str] = set()
        for run in items:
            for notification in run:
                # Notifications are tuples whose first element is the type.
                seen.add(notification[0])
        missing = sorted(self.expected - seen)
        return (not missing, {"seen": sorted(seen), "missing": missing})


class V3(Check):
    """Two runs with the same seed are identical.

    A pair where either run output is empty is not a comparison, so it is recorded as
    mismatched rather than passing vacuously.
    """

    name = "V3 pairs: same seed gives identical runs"

    def check(self, items: Iterable[dict]) -> tuple[bool, Any]:
        compared: list[Any] = []
        bad: list[Any] = []
        for pair in items:
            seed = pair["seed"]
            a = pair["a"]
            b = pair["b"]
            if is_empty(a) or is_empty(b):
                bad.append(seed)
                continue
            compared.append(seed)
            if a != b:
                bad.append(seed)
        return (not bad, {"compared": compared, "mismatched": bad})


class V4(Check):
    """Storage cost stayed within the budget on every day."""

    name = "V4 days: storage_cost_cents <= budget_cents"

    def check(self, items: Iterable[dict]) -> tuple[bool, Any]:
        checked: list[int] = []
        over: list[int] = []
        for day in items:
            d = day["day"]
            cost = day["storage_cost_cents"]
            budget = day["budget_cents"]
            checked.append(d)
            if not (_is_int(cost) and _is_int(budget) and cost <= budget):
                over.append(d)
        return (not over, {"checked": checked, "over_budget": over})


class V5(Check):
    """Every clause has at least one test.

    A test name counts only if it is a non-blank string.
    """

    name = "V5 clauses: every clause has a test"

    def check(self, items: Iterable[dict]) -> tuple[bool, Any]:
        covered: list[str] = []
        uncovered: list[str] = []
        for entry in items:
            cid = entry["clause_id"]
            tests = [t for t in entry["tests"] if isinstance(t, str) and t.strip()]
            if tests:
                covered.append(cid)
            else:
                uncovered.append(cid)
        return (not uncovered, {"covered": covered, "uncovered": uncovered})


class V6(Check):
    """Results from two implementations agree on every compared pair.

    Agreement means equal values of the same top-level type, so ``0`` vs ``None`` (or
    ``5`` vs ``5.0``) is a disagreement. ``None`` vs ``None`` is agreement, because
    ``turnover`` legitimately returns ``None``.
    """

    name = "V6 pairs: two implementations agree"

    def check(self, items: Iterable[dict]) -> tuple[bool, Any]:
        compared: list[Any] = []
        disagree: list[Any] = []
        for pair in items:
            key = pair["key"]
            a = pair["a"]
            b = pair["b"]
            compared.append(key)
            if not (type(a) is type(b) and a == b):
                disagree.append(key)
        return (not disagree, {"compared": compared, "disagree": disagree})
```

`checks_base.py`:

```
"""The ``Check`` base class: a check never passes on nothing (brief 3, and E2's guard condition).

``Check.run(items)`` returns ``failed: empty input`` for empty or all-unmeasured input *before*
calling the subclass, and ``failed: nothing measured`` when the subclass measured nothing. The
harness's own checks (presence, reach, parity, mutation) subclass it, and so do the agent's
validators in E2's guard condition (the agent gets this file as ``checks_base.py``).

This file is standard-library only so it can be copied verbatim into the agent's repo.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class CheckResult:
    passed: bool
    measured: Any
    reason: str = ""

    def __iter__(self):  # allows ``passed, measured = check.run(x)``
        yield self.passed
        yield self.measured

    def __bool__(self) -> bool:
        return bool(self.passed)


def is_empty(value: Any) -> bool:
    """True for None, empty containers, and containers whose every leaf is None or empty."""
    if value is None:
        return True
    if isinstance(value, (str, bytes)):
        return len(value) == 0
    if isinstance(value, dict):
        return len(value) == 0 or all(is_empty(v) for v in value.values())
    if isinstance(value, (list, tuple, set, frozenset)):
        return len(value) == 0 or all(is_empty(v) for v in value)
    return False


class Check:
    """Subclasses implement ``check(items) -> (passed, measured)``; callers use ``run(items)``."""

    name = "check"

    def run(self, items: Any) -> CheckResult:
        if hasattr(items, "__next__"):  # a lazy source of runs: materialise before judging emptiness
            items = list(items)
        if is_empty(items):
            return CheckResult(False, None, "failed: empty input")
        try:
            passed, measured = self.check(items)
        except Exception as exc:  # a check that crashes has not passed
            return CheckResult(False, None, f"failed: {type(exc).__name__}: {exc}")
        if is_empty(measured):
            return CheckResult(False, measured, "failed: nothing measured")
        return CheckResult(bool(passed), measured, "" if passed else "failed")

    def check(self, items: Any) -> tuple[bool, Any]:  # pragma: no cover - abstract
        raise NotImplementedError
```

