<file path="validators_later.py">
"""Later validators (V7 to V9) over depot run outputs. Same form as ``validators.py``.

Callers use ``VN().run(items)``. ``check`` returns ``(passed, measured)``. When a validator
measures nothing, ``measured`` is an empty container, so ``Check.run`` reports
``failed: nothing measured``.
"""
from __future__ import annotations

from collections import Counter
from typing import Any, Iterable

from checks_base import Check
from validators import _is_int


def _is_triple(item: Any) -> bool:
    """True for a [sku, wh, qty] triple: str sku, str wh, int qty (not bool)."""
    return (
        isinstance(item, (list, tuple))
        and len(item) == 3
        and isinstance(item[0], str)
        and isinstance(item[1], str)
        and _is_int(item[2])
    )


def _unmatched_expiries(entry: dict) -> list:
    """Expired items with no matching notified item, counting multiplicity.

    Malformed notified items are not counted as notifications. Malformed expired items
    are reported as unmatched.
    """
    notified = Counter(tuple(t) for t in entry["notified"] if _is_triple(t))
    unmatched: list = []
    for item in entry["expired"]:
        if not _is_triple(item) or notified[tuple(item)] == 0:
            unmatched.append(item)
        else:
            notified[tuple(item)] -= 1
    return unmatched


class V7(Check):
    """Every warehouse's capacity was respected across runs (max_units <= capacity)."""

    name = "V7 warehouses: max_units <= capacity"

    def check(self, items: Iterable[dict]) -> tuple[bool, Any]:
        checked: list[str] = []
        over: list[str] = []
        for entry in items:
            wh = entry["wh"]
            capacity = entry["capacity"]
            max_units = entry["max_units"]
            checked.append(wh)
            if not (_is_int(capacity) and _is_int(max_units) and max_units <= capacity):
                over.append(wh)
        return (not over, {"checked": checked, "over_capacity": over})


class V8(Check):
    """All expiries were notified: every expired [sku, wh, qty] has a matching notification.

    Matching is by exact triple, and multiplicity counts, so two expiries need two
    notifications.
    """

    name = "V8 expiries: every expiry notified"

    def check(self, items: Iterable[dict]) -> tuple[bool, Any]:
        checked: list[int] = []
        unnotified: list[list] = []
        for index, entry in enumerate(items):
            checked.append(index)
            for item in _unmatched_expiries(entry):
                unnotified.append([index, item])
        return (not unnotified, {"checked": checked, "unnotified": unnotified})


class V9(Check):
    """Every supplier's reliability stayed in range (LOW <= reliability <= HIGH).

    The range defaults to 0 to 100 inclusive. Pass ``low`` and ``high`` to override it.
    """

    name = "V9 suppliers: reliability in range"

    LOW = 0
    HIGH = 100

    def __init__(self, low: int | None = None, high: int | None = None) -> None:
        self.low = self.LOW if low is None else low
        self.high = self.HIGH if high is None else high

    def check(self, items: Iterable[dict]) -> tuple[bool, Any]:
        checked: list[str] = []
        out_of_range: list[str] = []
        for entry in items:
            supplier = entry["supplier"]
            reliability = entry["reliability"]
            checked.append(supplier)
            if not (_is_int(reliability) and self.low <= reliability <= self.high):
                out_of_range.append(supplier)
        return (not out_of_range, {"checked": checked, "out_of_range": out_of_range})
