"""Tests for V7 to V9 in ``validators_later.py``. Run from the repository root."""
from __future__ import annotations

import unittest

from validators_later import V7, V8, V9


class TestV7(unittest.TestCase):
    def test_capacity_respected_passes(self) -> None:
        result = V7().run([{"wh": "A", "capacity": 10, "max_units": 10}])
        self.assertTrue(result.passed)

    def test_over_capacity_fails_and_names_warehouse(self) -> None:
        result = V7().run([
            {"wh": "A", "capacity": 10, "max_units": 11},
            {"wh": "B", "capacity": 10, "max_units": 3},
        ])
        self.assertFalse(result.passed)
        self.assertEqual(result.measured["over_capacity"], ["A"])

    def test_bool_capacity_fails(self) -> None:
        result = V7().run([{"wh": "A", "capacity": True, "max_units": 1}])
        self.assertFalse(result.passed)

    def test_float_units_fail(self) -> None:
        result = V7().run([{"wh": "A", "capacity": 10, "max_units": 1.0}])
        self.assertFalse(result.passed)

    def test_empty_input_fails(self) -> None:
        self.assertFalse(V7().run([]).passed)


class TestV8(unittest.TestCase):
    def test_all_expiries_notified_passes(self) -> None:
        result = V8().run([
            {"expired": [["s1", "A", 2]], "notified": [["s1", "A", 2]]},
        ])
        self.assertTrue(result.passed)

    def test_missing_notification_fails(self) -> None:
        result = V8().run([{"expired": [["s1", "A", 2]], "notified": []}])
        self.assertFalse(result.passed)
        self.assertEqual(result.measured["unnotified"], [[0, ["s1", "A", 2]]])

    def test_quantity_mismatch_fails(self) -> None:
        result = V8().run([{"expired": [["s1", "A", 2]], "notified": [["s1", "A", 3]]}])
        self.assertFalse(result.passed)

    def test_multiplicity_counts(self) -> None:
        result = V8().run([
            {"expired": [["s1", "A", 2], ["s1", "A", 2]], "notified": [["s1", "A", 2]]},
        ])
        self.assertFalse(result.passed)

    def test_extra_notifications_are_fine(self) -> None:
        result = V8().run([
            {"expired": [["s1", "A", 2]], "notified": [["s1", "A", 2], ["s9", "B", 1]]},
        ])
        self.assertTrue(result.passed)

    def test_malformed_expired_item_fails(self) -> None:
        result = V8().run([{"expired": [["s1", "A"]], "notified": [["s1", "A", 2]]}])
        self.assertFalse(result.passed)

    def test_malformed_notification_does_not_count(self) -> None:
        result = V8().run([{"expired": [["s1", "A", 2]], "notified": [["s1", "A", True]]}])
        self.assertFalse(result.passed)

    def test_empty_input_fails(self) -> None:
        self.assertFalse(V8().run([]).passed)


class TestV9(unittest.TestCase):
    def test_in_range_passes(self) -> None:
        self.assertTrue(V9().run([{"supplier": "S", "reliability": 50}]).passed)

    def test_bounds_are_inclusive(self) -> None:
        result = V9().run([
            {"supplier": "lo", "reliability": 0},
            {"supplier": "hi", "reliability": 100},
        ])
        self.assertTrue(result.passed)

    def test_above_range_fails(self) -> None:
        result = V9().run([{"supplier": "S", "reliability": 101}])
        self.assertFalse(result.passed)
        self.assertEqual(result.measured["out_of_range"], ["S"])

    def test_below_range_fails(self) -> None:
        self.assertFalse(V9().run([{"supplier": "S", "reliability": -1}]).passed)

    def test_bool_and_string_fail(self) -> None:
        self.assertFalse(V9().run([{"supplier": "S", "reliability": True}]).passed)
        self.assertFalse(V9().run([{"supplier": "S", "reliability": "50"}]).passed)

    def test_custom_range(self) -> None:
        self.assertTrue(V9(low=10, high=20).run([{"supplier": "S", "reliability": 15}]).passed)
        self.assertFalse(V9(low=10, high=20).run([{"supplier": "S", "reliability": 25}]).passed)

    def test_empty_input_fails(self) -> None:
        self.assertFalse(V9().run([]).passed)


if __name__ == "__main__":
    unittest.main()
</file>

<notes>
- V9's range was not in the spec. I assumed 0 to 100 inclusive. It is set by the `LOW`/`HIGH` class attributes and can be overridden with `V9(low=..., high=...)`. Please confirm the range.
- V7 treats `max_units == capacity` as passing, since "respected" reads as "not exceeded".
- V8 matches expiries to notifications by exact `[sku, wh, qty]` triple with multiplicity. The spec does not say whether quantity must match, so tell me if matching should be by `(sku, wh)` only.
- V8 and V9 reuse `_is_int` from `validators.py`, which is a private helper imported across modules. I kept it to avoid duplicating the bool-exclusion rule.
- Tests use `unittest` from the standard library, run from the repo root so `checks_base` and `validators` import. I have not run them.
</notes>
